from pathlib import Path
import unittest
namespace = {}
exec(compile(Path("source.py").read_bytes(), "source.py", "exec"), namespace)
Order = namespace["Order"]
class OwnerOutcome(unittest.TestCase):
    def setUp(self):
        self.order = Order()
        self.order.apply(3)
    def test_displayed_quantity(self):
        self.assertEqual(self.order.displayed_quantity, 3)
    def test_model_quantity(self):
        self.assertEqual(self.order.quantity, 3)
    def test_subtotal_consumer(self):
        # Owner givens independently imply 3 * 7 = 21.
        self.assertEqual(self.order.subtotal(), 21)
    def test_preserved_unit_price(self):
        self.assertEqual(self.order.unit_price, 7)
unittest.main(verbosity=2)
